      "indicator": "MM20",
      "reading": "36.6080",
      "interpretation": "Preço (36.72) ligeiramente acima da MM20; MM20 atua como suporte imediato e confirma tendência de curto prazo."
    },
    {
      "indicator": "MM50",
      "reading": "35.7520",
      "interpretation": "MM50 abaixo do preço; suporte de médio prazo alinhado com viés de alta."
    },
    {
      "indicator": "MM200",
      "reading": "33.5507",
      "interpretation": "MM200 bem abaixo do preço atual; confirma viés de alta de longo prazo."
    },
    {
      "indicator": "EMA9",
      "reading": "36.7964",
      "interpretation": "EMA9 > EMA21 indica tendência de curtíssimo prazo compradora, mas o fechamento ficou ligeiramente abaixo da EMA9 — sinal de correção."
    },
    {
      "indicator": "EMA21",
      "reading": "36.5613",
      "interpretation": "EMA21 está abaixo do preço e serve como suporte de curtíssimo prazo, corroborando o viés positivo."
    },
    {
      "indicator": "MACD",
      "reading": "MACD=0.2912; signal=0.3208; hist=-0.0296",
      "interpretation": "MACD positivo indica viés comprador de base; MACD < signal e hist negativo apontam perda de impulso no curto prazo."
    },
    {
      "indicator": "Bandas de Bollinger",
      "reading": "BB_lower=35.9109; BB_mid=36.6080; BB_upper=37.3051 (largura≈1.3942)",
      "interpretation": "Preço entre média e banda superior; bandas com largura moderada, sem squeeze — espaço até ~37.30 antes de resistência."
    },
    {
      "indicator": "RSI14",
      "reading": "53.4194",
      "interpretation": "Neutro; não há sinal de sobrecompra ou sobrevenda, confirma ausência de impulso extremo."
    },
    {
      "indicator": "Volume",
      "reading": "24189002200 (~24.19 bilhões)",
      "interpretation": "Volume em linha com o pregão anterior e inferior a picos recentes; não confirma aceleração forte na alta atual."
    }
  ]
}
